#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT RigidBodyPhysics : 2

DEF RBC RigidBodyCollection {
  gravity 0 0 0
  bodies [
    DEF A RigidBody {
      fixed TRUE
      position 0 5 0
      geometry DEF A_C CollidableShape {
        translation 0 5 0
        shape Shape {
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      }
    }
    DEF B RigidBody {
      position 1.003983 5 0
      linearVelocity 0.2103481 0 0
      forces 5 0 0
      geometry DEF B_C CollidableShape {
        translation 1.003983 5 0
        shape Shape {
          geometry Box {
            size 1 1 1
          }
        }
      }
    }
  ]
  joints DEF J SliderJoint {
    forceOutput "ALL"
    axis 1 0 0
    maxSeparation 2
    sliderForce 3
    body1 USE A
    body2 USE B
  }
}

